floor_fn:
"""Populate dest with data from the given function.

    Args:
        title: The name of the data
        func: The function which will return the data
        dest: a dict which will store the data

    Returns:
        dest: The modified destination dict

    """
def _get_data(title: Any, func: Any, dest: Any) -> object {
    values = func();
    for (key, value) in values.items() {
        dest[key][title] = value;
    }
    return dest;
}

test_blocks:
test "t0" {
    assert (
        _get_data("title1", lambda() { {"key1": "value1"}; }, {"key1": {}})
        == {"key1": {"title1": "value1"}}
    );;
}

test "t1" {
    assert (
        _get_data("test", lambda() { {"one": 1, "two": 2}; }, {"one": {}, "two": {}})
